// ===== Count-up stat =====
const Counter = ({ target, suffix, duration = 2000 }) => {
    const [count, setCount] = useState(0);
    const ref = useRef(null);
    const hasAnimated = useRef(false);

    useEffect(() => {
        const observer = new IntersectionObserver(
            ([entry]) => {
                if (entry.isIntersecting && !hasAnimated.current) {
                    hasAnimated.current = true;
                    let start = 0;
                    const stepTime = Math.max(Math.floor(duration / target), 16);
                    const increment = Math.ceil(target / (duration / stepTime));

                    const timer = setInterval(() => {
                        start += increment;
                        if (start >= target) {
                            start = target;
                            clearInterval(timer);
                        }
                        setCount(start);
                    }, stepTime);
                }
            },
            { threshold: 0.3 }
        );

        if (ref.current) observer.observe(ref.current);
        return () => observer.disconnect();
    }, [target, duration]);

    return (
        <h3 ref={ref} className="who-are-we__stat-number">
            {count}
            {suffix}
        </h3>
    );
};

// ===== Floating particle background =====
const ParticleLayer = () => {
    const canvasRef = useRef(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        const ctx = canvas.getContext("2d");
        let particles = [];
        let animationId;
        let width, height;

        const resize = () => {
            width = canvas.width = canvas.offsetWidth;
            height = canvas.height = canvas.offsetHeight;
        };

        const createParticles = () => {
            particles = Array.from({ length: 50 }, () => ({
                x: Math.random() * width,
                y: Math.random() * height,
                r: Math.random() * 1.8 + 0.6,
                speedX: (Math.random() - 0.5) * 0.2,
                speedY: (Math.random() - 0.5) * 0.2,
                opacity: Math.random() * 0.5 + 0.15,
            }));
        };

        const animate = () => {
            ctx.clearRect(0, 0, width, height);
            particles.forEach((p) => {
                p.x += p.speedX;
                p.y += p.speedY;

                if (p.x < 0) p.x = width;
                if (p.x > width) p.x = 0;
                if (p.y < 0) p.y = height;
                if (p.y > height) p.y = 0;

                ctx.beginPath();
                ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
                ctx.fillStyle = `rgba(255, 107, 53, ${p.opacity})`;
                ctx.fill();
            });
            animationId = requestAnimationFrame(animate);
        };

        resize();
        createParticles();
        animate();

        const handleResize = () => {
            resize();
            createParticles();
        };
        window.addEventListener("resize", handleResize);

        return () => {
            cancelAnimationFrame(animationId);
            window.removeEventListener("resize", handleResize);
        };
    }, []);

    return <canvas ref={canvasRef} className="who-are-we__particles" />;
};

// ===== Continuous typewriter heading (types, pauses, deletes, repeats forever) =====
const HERO_TITLE_SEGMENTS = [
    { text: "Beyond Code. Beyond Conventional." },
    // { text: "Building Digital Systems", className: "c_primary" },
    // { text: " That Last" },
];

const TypewriterHeading = ({
    segments,
    className,
    typingSpeed = 42,
    deletingSpeed = 22,
    pauseAfterTyping = 2200,
    pauseAfterDeleting = 500,
}) => {
    const fullText = segments.map((s) => s.text).join("");
    const totalLength = fullText.length;
    const [charCount, setCharCount] = useState(0);
    const [isDeleting, setIsDeleting] = useState(false);

    useEffect(() => {
        let timeout;

        if (isDeleting) {
            if (charCount > 0) {
                timeout = setTimeout(() => setCharCount((c) => c - 1), deletingSpeed);
            } else {
                timeout = setTimeout(() => setIsDeleting(false), pauseAfterDeleting);
            }
        } else {
            if (charCount < totalLength) {
                timeout = setTimeout(() => setCharCount((c) => c + 1), typingSpeed);
            } else {
                timeout = setTimeout(() => setIsDeleting(true), pauseAfterTyping);
            }
        }

        return () => clearTimeout(timeout);
    }, [charCount, isDeleting, totalLength, typingSpeed, deletingSpeed, pauseAfterTyping, pauseAfterDeleting]);

    let remaining = charCount;
    const rendered = segments.map((seg, i) => {
        const shown = Math.max(0, Math.min(seg.text.length, remaining));
        remaining -= seg.text.length;
        return (
            <span key={i} className={seg.className}>
                {seg.text.slice(0, shown)}
            </span>
        );
    });

    return (
        <h1 className={className} aria-label={fullText}>
            <span aria-hidden="true">
                {rendered}
                <span className="typewriter-cursor" />
            </span>
        </h1>
    );
};

